using System.ComponentModel;
using System.Text.Json;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Tool Definitions ---

class WebSearchTool
{
    private static readonly HttpClient _http = new();

    [Description("Searches the web for a given query and returns relevant results as text snippets.")]
    public static async Task<string> SearchWeb(
        [Description("The search query")] string query)
    {
        Console.WriteLine($"  [WebSearch] Searching for: \"{query}\"");

        // Use a simple web search API (DuckDuckGo instant answer API as a fallback)
        try
        {
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1";
            var response = await _http.GetStringAsync(url);
            var doc = JsonDocument.Parse(response);
            var root = doc.RootElement;

            var results = new List<string>();

            // Abstract
            var abstractText = root.GetProperty("AbstractText").GetString();
            if (!string.IsNullOrWhiteSpace(abstractText))
                results.Add($"Summary: {abstractText}");

            // Related topics
            if (root.TryGetProperty("RelatedTopics", out var topics))
            {
                foreach (var topic in topics.EnumerateArray().Take(5))
                {
                    if (topic.TryGetProperty("Text", out var text))
                        results.Add($"- {text.GetString()}");
                }
            }

            if (results.Count == 0)
                return $"No detailed results found for '{query}'. Try refining the search terms.";

            return string.Join("\n", results);
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}. Please try a different query.";
        }
    }
}

class NoteTakingTool
{
    private static readonly List<string> _notes = [];

    [Description("Saves a research note for later reference. Use this to record key findings.")]
    public static string SaveNote(
        [Description("The note content to save")] string note)
    {
        _notes.Add(note);
        Console.WriteLine($"  [Notes] Saved note #{_notes.Count}");
        return $"Note #{_notes.Count} saved successfully.";
    }

    [Description("Retrieves all saved research notes.")]
    public static string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes have been saved yet.";

        var result = $"=== Research Notes ({_notes.Count} total) ===\n";
        for (int i = 0; i < _notes.Count; i++)
            result += $"\n[{i + 1}] {_notes[i]}";
        return result;
    }
}

// --- Main Program ---

Console.WriteLine("Research Agent Starting...\n");

var topic = args.Length > 0
    ? string.Join(' ', args)
    : "the impact of large language models on software development in 2025";

Console.WriteLine($"Research topic: \"{topic}\"\n");

// Configure the AI client
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY") ?? "your-api-key-here";
var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

var openAiClient = new OpenAIClient(apiKey);
IChatClient chatClient = openAiClient.GetChatClient(modelId).AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

// Register tools
var chatOptions = new ChatOptions
{
    Tools =
    [
        AIFunctionFactory.Create(WebSearchTool.SearchWeb),
        AIFunctionFactory.Create(NoteTakingTool.SaveNote),
        AIFunctionFactory.Create(NoteTakingTool.GetNotes),
    ]
};

// Agent system prompt
var messages = new List<ChatMessage>
{
    new(ChatRole.System, """
        You are a research agent. Your job is to research a topic thoroughly by:
        1. Searching the web for relevant information (make 2-3 searches with different queries)
        2. Saving key findings as notes using the note-taking tool
        3. Retrieving all your notes at the end
        4. Providing a comprehensive summary of your findings

        Be methodical: search, take notes on important findings, then summarize.
        """),
    new(ChatRole.User, $"Please research the following topic and provide a summary: {topic}")
};

Console.WriteLine("Agent is researching...\n");

var response = await chatClient.GetResponseAsync(messages, chatOptions);

Console.WriteLine("\n=== Agent Summary ===\n");
Console.WriteLine(response.Text);

